import java.util.*; import java.io.*; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null) return; int t = Integer.parseInt(line.trim()); while (t-- > 0) { String nStr = br.readLine(); if (nStr == null) break; int n = Integer.parseInt(nStr.trim()); char[][] grid = new char[n][n]; List<int[]> players = new ArrayList<int[]>(); List<int[]> mines = new ArrayList<int[]>(); for (int i = 0; i < n; i++) { String row = br.readLine(); for (int j = 0; j < n; j++) { grid[i][j] = row.charAt(j); if (grid[i][j] == '^') players.add(new int[]{i, j}); else if (grid[i][j] == '*') mines.add(new int[]{i, j}); } } int[][] dists = new int[2][2]; boolean possible = true; for (int i = 0; i < 2; i++) { int[][] d = bfs(grid, players.get(i), n); for (int j = 0; j < 2; j++) { int val = d[mines.get(j)[0]][mines.get(j)[1]]; if (val == -1) { possible = false; } dists[i][j] = val; } } if (!possible) { System.out.println("No"); } else { int opt1 = Math.max(dists[0][0], dists[1][1]); int opt2 = Math.max(dists[0][1], dists[1][0]); System.out.println("Yes"); System.out.println(Math.min(opt1, opt2)); } } } private static int[][] bfs(char[][] grid, int[] start, int n) { int[][] dist = new int[n][n]; for (int i = 0; i < n; i++) Arrays.fill(dist[i], -1); Queue<int[]> q = new LinkedList<int[]>(); q.add(start); dist[start[0]][start[1]] = 0; int[] dr = {0, 0, 1, -1}; int[] dc = {1, -1, 0, 0}; while (!q.isEmpty()) { int[] curr = q.poll(); for (int i = 0; i < 4; i++) { int nr = curr[0] + dr[i]; int nc = curr[1] + dc[i]; if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] != '#' && dist[nr][nc] == -1) { dist[nr][nc] = dist[curr[0]][curr[1]] + 1; q.add(new int[]{nr, nc}); } } } return dist; } }